# Generated by OrchestKit Claude Plugin
# Created: 2026-07-02

"""
Academic Writer — Contrastive Baseline Comparison

Compares a researcher's computed computationalMetrics against the shared
Hebrew academic-writing baseline (Trove book "Hebrew Linguistic
Reference", cached to markdown by the init skill). Per src/skills/init/SKILL.md,
the baseline is a JSON code block embedded in the cached markdown's
"08-style-fingerprint-baseline" chapter — there is no separate baseline JSON
file shipped with the plugin.
"""

from __future__ import annotations

import json
import re

_JSON_FENCE_RE = re.compile(r"```json\s*(\{.*?\})\s*```", re.DOTALL)

# Dot-paths of numeric leaves we compare between computed metrics and baseline.
CONTRASTIVE_METRIC_PATHS = [
    "sentenceLevel.length.mean",
    "sentenceLevel.passiveVoiceFrequency",
    "sentenceLevel.firstPersonFrequency",
    "paragraphStructure.length.mean",
    "paragraphStructure.sentencesPerParagraph.mean",
    "transitions.frequencyPerParagraph",
    "vocabulary.typeTokenRatio",
    "vocabulary.avgWordLength",
]

HIGH_RATIO = 1.2
LOW_RATIO = 0.8


def _looks_like_baseline(payload: object) -> bool:
    """True when a parsed fence actually carries baseline metrics.

    Identify the payload by the metrics it contains, not by the heading above
    it: the shipped Hebrew Linguistic Reference has a Hebrew chapter heading,
    so a Latin-only "baseline"/"08" heading match silently fell through to the
    first ```json fence in the file and compared against unrelated numbers.
    """
    if not isinstance(payload, dict):
        return False
    return any(
        isinstance(_get_path(payload, path), (int, float))
        for path in CONTRASTIVE_METRIC_PATHS
    )


def extract_baseline_json(markdown_text: str) -> tuple[dict | None, list[str]]:
    """Extract the baseline JSON code block from the cached markdown.

    Returns (payload, warnings). Selection is by content: the first ```json
    fence that parses and resolves at least one CONTRASTIVE_METRIC_PATHS leaf
    wins, regardless of the language of the heading above it. If no fence
    qualifies, the first parseable fence is used as a last resort *and a
    warning is emitted* — the previous silent fallback produced confident
    comparisons against the wrong numbers.
    """
    warnings: list[str] = []
    fences = list(_JSON_FENCE_RE.finditer(markdown_text))
    if not fences:
        return None, warnings

    parsed: list[dict] = []
    for fence in fences:
        try:
            payload = json.loads(fence.group(1))
        except json.JSONDecodeError:
            continue
        if _looks_like_baseline(payload):
            return payload, warnings
        if isinstance(payload, dict):
            parsed.append(payload)

    if parsed:
        warnings.append(
            "No JSON code block in --baseline carried recognizable baseline "
            "metrics (expected at least one of: "
            + ", ".join(CONTRASTIVE_METRIC_PATHS)
            + "); falling back to the first parseable JSON block. Contrastive "
            "results may compare against unrelated numbers."
        )
        return parsed[0], warnings

    return None, warnings


def _get_path(data: dict, dot_path: str):
    node = data
    for part in dot_path.split("."):
        if not isinstance(node, dict) or part not in node:
            return None
        node = node[part]
    return node


def compute_contrastive(computed_metrics: dict, baseline_metrics: dict) -> dict:
    """Classify each tracked metric as distinctively_high / distinctively_low
    / normal relative to the baseline. A metric missing from either side is
    reported as "unavailable"."""
    contrastive: dict[str, dict] = {}
    for path in CONTRASTIVE_METRIC_PATHS:
        computed_value = _get_path(computed_metrics, path)
        baseline_value = _get_path(baseline_metrics, path)
        if not isinstance(computed_value, (int, float)) or not isinstance(
            baseline_value, (int, float)
        ):
            contrastive[path] = {"status": "unavailable"}
            continue
        if baseline_value == 0:
            status = "distinctively_high" if computed_value > 0 else "normal"
        else:
            ratio = computed_value / baseline_value
            if ratio >= HIGH_RATIO:
                status = "distinctively_high"
            elif ratio <= LOW_RATIO:
                status = "distinctively_low"
            else:
                status = "normal"
        contrastive[path] = {
            "status": status,
            "researcherValue": computed_value,
            "baselineValue": baseline_value,
        }
    return contrastive
